select
  'nutrition-counseling-and-education',
  null,
  'Nutrition Counseling and Education',
  'Nutrition Counseling and Education',
  'This advanced undergraduate course develops evidence-informed nutrition counseling, education, and communication skills for diverse individuals and groups. Students integrate person-centered communication, motivational interviewing, behavior-change theory, the Nutrition Care Process, cultural humility, structural context, health literacy, instructional design, group facilitation, digital communication, eating-disorder safety, telehealth, documentation, and evaluation. Repeated simulations and feedback build observable competence in listening, assessment, shared agenda setting, information exchange, action planning, teach-back, group teaching, referral, and professional documentation. The course prepares students for supervised dietetics practice; it does not confer independent clinical or psychotherapy scope.',
  $ncejson${"slug": "nutrition-counseling-and-education", "title": "Nutrition Counseling and Education", "description": "This advanced undergraduate course develops evidence-informed nutrition counseling, education, and communication skills for diverse individuals and groups. Students integrate person-centered communication, motivational interviewing, behavior-change theory, the Nutrition Care Process, cultural humility, structural context, health literacy, instructional design, group facilitation, digital communication, eating-disorder safety, telehealth, documentation, and evaluation. Repeated simulations and feedback build observable competence in listening, assessment, shared agenda setting, information exchange, action planning, teach-back, group teaching, referral, and professional documentation. The course prepares students for supervised dietetics practice; it does not confer independent clinical or psychotherapy scope.", "topics": [{"id": "ed9b4d66-4f86-4f18-a2cf-090e93fd6d5f", "type": "topic", "title": "Foundations of Nutrition Counseling and Education", "description": "This opening section distinguishes counseling, education, coaching, health communication, and psychotherapy. Students learn what a nutrition professional can responsibly do, how each approach serves a different purpose, and why client autonomy is the organizing principle.", "children": [{"id": "7200a5a0-6eb7-46b9-ba07-091a7a8243ca", "type": "subtopic", "title": "Counseling, education, and coaching", "description": "Students select the right helping mode instead of defaulting to advice. Counseling supports exploration and change; education builds knowledge or skill; coaching supports self-directed action.", "children": [{"id": "c6d19040-37bb-47b3-8e6f-1349f79a30e4", "type": "concept", "title": "Purpose, stance, typical structure, and indicators for each mode"}, {"id": "44775154-7313-448f-b5c4-2cff69f9e39c", "type": "concept", "title": "Expert-driven, collaborative, and client-led communication"}, {"id": "4cfadd4f-b049-46f0-9c16-44345863ee39", "type": "concept", "title": "Switching modes transparently and asking permission before providing information"}]}, {"id": "433c9f1b-9966-44da-9dd0-73f15995a1fd", "type": "subtopic", "title": "Professional role and scope", "description": "This subtopic clarifies the boundaries of undergraduate practice and the difference between nutrition counseling and mental-health treatment.", "children": [{"id": "14716243-5cc6-4c46-bb62-a93b4a2f3436", "type": "concept", "title": "Dietetics scope, supervision, referral, and jurisdictional variation"}, {"id": "b9e29d91-c4bb-43ef-93bd-9d25329dc943", "type": "concept", "title": "Nutrition diagnosis versus psychiatric diagnosis; coaching versus psychotherapy"}, {"id": "5f7681f0-98d7-4875-ba9a-04021c0575d2", "type": "concept", "title": "Interprofessional roles, handoffs, consultation, and emergency escalation"}]}, {"id": "1af4de62-a808-4925-a780-2dfc6917553b", "type": "subtopic", "title": "Evidence-informed, person-centered practice", "description": "Students learn to integrate research, practitioner expertise, context, and the client's values rather than presenting evidence as a command.", "children": [{"id": "0e50acee-dfd5-4df0-b5e9-c32f7758e4b0", "type": "concept", "title": "Evidence quality, uncertainty, applicability, and shared decisions"}, {"id": "83d1e6fd-fc11-4f1f-8281-1a63e4830b8b", "type": "concept", "title": "Autonomy, dignity, strengths, preferences, lived experience, and treatment burden"}, {"id": "9bb8970e-ef2e-4f2b-bced-c78b447390d2", "type": "concept", "title": "Outcome goals that include function, well-being, access, and quality of life"}]}]}, {"id": "1cd2c17a-81c6-4622-bfe2-69beecb22060", "type": "topic", "title": "Counseling Relationship, Ethics, and Psychological Safety", "description": "A productive relationship is not a soft extra; it determines what information is shared, whether recommendations fit, and whether a person returns. Students practice trustworthy, boundaried, and nonjudgmental care.", "children": [{"id": "bc5a6d3d-73e6-4e85-92d5-563fc9402b2c", "type": "subtopic", "title": "Rapport, alliance, and trust", "description": "Students learn how presence, reliability, warmth, and accurate empathy create a working alliance without pretending to know another person's experience.", "children": [{"id": "fb6641a4-1867-424a-bda3-b9c494ff15f0", "type": "concept", "title": "Opening a session, role clarity, agenda negotiation, and confidentiality"}, {"id": "1fb5afcb-6cc3-4bcc-88f6-441e17858ff9", "type": "concept", "title": "Empathy, genuineness, respect, acceptance, and collaborative language"}, {"id": "1955272c-2e24-4c74-920c-056be3210b56", "type": "concept", "title": "Alliance ruptures, repair, feedback, and maintaining trust when priorities differ"}]}, {"id": "fd8debe3-e481-49b4-85de-52641cda8633", "type": "subtopic", "title": "Ethical practice and boundaries", "description": "The point is to recognize conflicts, power, privacy, and dual-role risks before they harm a client or the profession.", "children": [{"id": "c55a5b67-cb73-4956-9845-ad534f70c62b", "type": "concept", "title": "Autonomy, beneficence, nonmaleficence, justice, veracity, and fidelity"}, {"id": "c80238d2-2d9d-4408-a93a-2c80f467cc26", "type": "concept", "title": "Consent, privacy, record access, gifts, social media, self-disclosure, and conflicts of interest"}, {"id": "8895c0a8-4629-4913-9ad4-15acaf0e45a7", "type": "concept", "title": "Commercial influence, testimonials, supplement sales, sponsorship, and transparent evidence"}]}, {"id": "a3d889e3-540a-4ae1-bfb5-d7e28033fb86", "type": "subtopic", "title": "Trauma-informed communication", "description": "Students use universal precautions that reduce shame and coercion without asking clients to disclose trauma or attempting trauma therapy.", "children": [{"id": "c1e3ffc4-8fe0-4322-85e9-cd1f7377763b", "type": "concept", "title": "Safety, trustworthiness, choice, collaboration, empowerment, and cultural context"}, {"id": "95ea793e-0fe1-4d1a-8b2e-0a1356cb3441", "type": "concept", "title": "Predictability, permission, control over weighing/examination context, and non-shaming language"}, {"id": "ae762c7a-8d12-4629-a561-745e817eb973", "type": "concept", "title": "Recognizing activation, pausing, grounding within scope, and referral to qualified care"}]}]}, {"id": "19748e42-55ea-49eb-bbdf-37833f50bad9", "type": "topic", "title": "Core Communication Micro-Skills", "description": "Micro-skills make collaboration observable and teachable. Students deliberately practice listening, reflection, questioning, summarizing, and information exchange, then examine how each response changes the conversation.", "children": [{"id": "f885d9d6-cc6d-4cd8-8e4a-edfe315150f1", "type": "subtopic", "title": "Attending and nonverbal communication", "description": "Students learn to communicate attention across in-person, telephone, interpreter-mediated, and video encounters.", "children": [{"id": "3a2495b4-2774-48b8-8ce1-3d53a99faa78", "type": "concept", "title": "Eye contact preferences, posture, pacing, silence, facial expression, and vocal tone"}, {"id": "9b418a3b-8649-44ee-9fe7-920f6f681e15", "type": "concept", "title": "Environment, privacy, interruptions, seating, accessibility, and technology"}, {"id": "644f5e3e-587d-465b-ba43-e83b4dc8c9f6", "type": "concept", "title": "Observing without overinterpreting emotion, culture, disability, or neurotype"}]}, {"id": "d0977769-2706-42a6-a4eb-2dee434067ad", "type": "subtopic", "title": "Questions, reflections, and summaries", "description": "The goal is to elicit meaning rather than conduct an interrogation or rush to solutions.", "children": [{"id": "c08deaf1-8cdf-48a0-9589-463b75e83828", "type": "concept", "title": "Open versus closed questions; focused, evocative, and scaling questions"}, {"id": "2143709d-3040-405d-97f6-52fbed4470e9", "type": "concept", "title": "Simple and complex reflections; content, feeling, meaning, and ambivalence"}, {"id": "d2861282-8d85-4b2b-90d2-911303dca4f9", "type": "concept", "title": "Collecting, linking, and transitional summaries; checking accuracy"}]}, {"id": "1010e4a5-8b93-4919-a103-a20cbab85364", "type": "subtopic", "title": "Empathy, affirmation, and information exchange", "description": "Students practice validating effort and perspective while avoiding empty praise or reassurance.", "children": [{"id": "54bb5534-f257-487b-8ea3-c3cedc3f5e46", "type": "concept", "title": "Specific strengths-based affirmations and normalization without minimization"}, {"id": "aa5178d5-ddc4-4b0d-bb6c-1f5a4fec1e88", "type": "concept", "title": "Elicit-provide-elicit, ask-tell-ask, chunking, and choice of information"}, {"id": "91ddc67a-cbc6-4409-85c9-46028f38889d", "type": "concept", "title": "Permission, neutral options, correcting misinformation, and preserving autonomy"}]}]}, {"id": "36583508-ff53-4a50-9a18-c36d470cade3", "type": "topic", "title": "Motivational Interviewing", "description": "Motivational interviewing provides a coherent method for conversations about change when motivation is mixed. Students learn the spirit, processes, and skills while avoiding manipulation or using MI as a script.", "children": [{"id": "95c4fd2b-ccb2-4238-85e7-bb148af14a06", "type": "subtopic", "title": "MI spirit and four processes", "description": "Students ground techniques in partnership, acceptance, compassion, and evocation, moving flexibly through engaging, focusing, evoking, and planning.", "children": [{"id": "22aeb0ad-099f-43ec-b9ba-0f9ceb853efc", "type": "concept", "title": "Partnership, autonomy support, accurate empathy, affirmation, and compassion"}, {"id": "1f30dc3e-48f5-48ac-855a-24c4ef389364", "type": "concept", "title": "Engaging before focusing; shared agenda and target behavior"}, {"id": "858b2c01-5f3d-4aea-9915-d2a20e0ca8ce", "type": "concept", "title": "Evoking before planning; returning to engagement when discord appears"}]}, {"id": "2d3254da-4e4a-4f1e-878a-374805c4deca", "type": "subtopic", "title": "Change talk, sustain talk, and discord", "description": "Students listen for the person's own language about change and respond without arguing against reasons to stay the same.", "children": [{"id": "a49de9f8-7e7c-4204-bd56-5a974288fbff", "type": "concept", "title": "Desire, ability, reasons, need, commitment, activation, and taking steps"}, {"id": "39b828dc-837a-4527-9b52-ca4026dbf437", "type": "concept", "title": "Preparatory versus mobilizing change talk; strength and frequency"}, {"id": "71e69afa-fc2e-4fd3-8c8e-613089002f15", "type": "concept", "title": "Sustain talk versus relational discord; reflections, double-sided reflections, and shifting focus"}]}, {"id": "b5500860-3dd4-4c39-a657-88a8d0c3ab7f", "type": "subtopic", "title": "Evoking and strengthening motivation", "description": "The aim is to help clients hear and organize their own motivations, not to manufacture consent.", "children": [{"id": "a8db2a86-30db-41f9-8ec1-48c46fd1e682", "type": "concept", "title": "Evocative questions, importance/confidence rulers, looking forward/back, and values exploration"}, {"id": "91d4f542-d230-4f58-9760-4c1f77f4214e", "type": "concept", "title": "Selective reflection, elaboration, summaries, and querying extremes with care"}, {"id": "be9c36a5-dd53-4b79-be9f-21415f5650fe", "type": "concept", "title": "Recognizing readiness for planning and avoiding premature action plans"}]}]}, {"id": "1092da14-5fcd-4d88-bd54-62756acd0489", "type": "topic", "title": "Behavior-Change Theory and Case Formulation", "description": "Theories are lenses for explaining behavior and selecting intervention targets. Students compare models, identify their limitations, and build a formulation that includes individual, interpersonal, environmental, and structural influences.", "children": [{"id": "422efb30-9412-459c-a5fe-8d646886b727", "type": "subtopic", "title": "Stage and belief models", "description": "Students use stage and belief constructs as hypotheses—not labels that define a person or dictate a fixed intervention.", "children": [{"id": "73c9e693-217d-4d38-912c-a8c8f2752f2e", "type": "concept", "title": "Transtheoretical Model/stages of change, processes, decisional balance, and self-efficacy"}, {"id": "d307012a-9b8f-49dc-9168-7e43ca91d5af", "type": "concept", "title": "Health Belief Model: susceptibility, severity, benefits, barriers, cues, and efficacy"}, {"id": "32596474-43d4-4431-9036-e22b2f769ea4", "type": "concept", "title": "Theory of Planned Behavior: attitudes, norms, perceived control, intentions, and intention-behavior gap"}]}, {"id": "9282695e-64a0-4aed-83e0-1ea345ad2a35", "type": "subtopic", "title": "Capability, opportunity, motivation, and self-regulation", "description": "This subtopic broadens the analysis beyond willingness by asking whether a behavior is possible, supported, and sustainable.", "children": [{"id": "d56b7c3e-4cb7-42e7-b294-80d34b706097", "type": "concept", "title": "COM-B and Behavior Change Wheel concepts"}, {"id": "daf0351e-1f35-457f-a37d-133467b1cdf8", "type": "concept", "title": "Social Cognitive Theory: reciprocal determinism, modeling, outcome expectations, and self-efficacy"}, {"id": "a7324174-8a99-42c0-938f-206f92920cfb", "type": "concept", "title": "Self-Determination Theory: autonomy, competence, relatedness, and internalization"}]}, {"id": "18d3a13d-ba6b-4958-a7d9-ae42b6828105", "type": "subtopic", "title": "Ecological and systems formulation", "description": "Students connect behavior to family, food environments, institutions, policy, marketing, transportation, and material resources.", "children": [{"id": "0db1b1c4-01ab-468d-9493-c10b4b784f26", "type": "concept", "title": "Social-ecological levels and social determinants of health"}, {"id": "e4df5b65-77e4-4505-9fda-d9e8f929de49", "type": "concept", "title": "Habit, affect, identity, stress, executive function, and automatic versus reflective processes"}, {"id": "202c7f55-36ea-41d0-a96c-5cffc420d469", "type": "concept", "title": "Causal maps, modifiable drivers, leverage points, and avoiding individual-blame explanations"}]}]}, {"id": "8a7fd694-7bcc-41dc-bf5b-34dbce34c1b5", "type": "topic", "title": "Assessment, Readiness, and Shared Agenda", "description": "Good counseling begins with understanding what matters, what is happening, and what is realistically changeable. Students conduct focused assessment without turning the session into data extraction.", "children": [{"id": "d634fc4b-907f-4eae-8d92-fff5872f8d7e", "type": "subtopic", "title": "Whole-person nutrition assessment", "description": "Students connect food patterns with symptoms, medical priorities, function, relationships, culture, resources, and daily routines.", "children": [{"id": "cbbc18d5-3f66-40b7-92c3-0418fb932d88", "type": "concept", "title": "Presenting concern, nutrition history, health data, medications, sleep, movement, stress, and function"}, {"id": "c12a26db-2746-4980-8d23-ef852aafc662", "type": "concept", "title": "Food access, cooking facilities, time, money, transportation, caregiving, and work"}, {"id": "48cd7b21-6385-4c28-b511-081e0d13eaf6", "type": "concept", "title": "Strengths, prior attempts, preferences, fears, supports, and current strategies"}]}, {"id": "a9eb4595-2bb6-411d-9494-7a1376dd0967", "type": "subtopic", "title": "Readiness, confidence, and ambivalence", "description": "The aim is to understand motivation as dynamic and context-specific rather than a fixed trait.", "children": [{"id": "e49466f1-a3fe-4b6d-bd5d-bb12a0676438", "type": "concept", "title": "Importance, confidence, priority, timing, and competing demands"}, {"id": "84831e7c-b194-4dc1-a369-60af8bfad52e", "type": "concept", "title": "Values and discrepancy without confrontation"}, {"id": "63bee6b3-bb87-4b21-be32-bee39103e582", "type": "concept", "title": "Ambivalence, resistance as interaction, autonomy, and when not to pursue change"}]}, {"id": "e40cdfd3-0725-4322-a045-76001ebd10f8", "type": "subtopic", "title": "Collaborative focus and session structure", "description": "Students learn to create enough structure for progress while keeping the client's priorities visible.", "children": [{"id": "6a0662b1-48d1-4cad-8dff-3010d3966869", "type": "concept", "title": "Opening, agenda map, time check, shared focus, transition, summary, and close"}, {"id": "fa851de5-cdb1-472e-90de-38288174dc01", "type": "concept", "title": "Multiple concerns, urgent issues, referral needs, and narrowing scope"}, {"id": "dee3a62e-e640-4ab3-b9cb-30cfbb36afd4", "type": "concept", "title": "Follow-up from prior sessions, continuity, and unfinished topics"}]}]}, {"id": "9f51aa57-f0d2-47b6-86f4-dd5769a4541f", "type": "topic", "title": "Collaborative Goals, Action Planning, and Maintenance", "description": "Plans work when they are meaningful, feasible, specific, and revisable. Students practice translating insight into experiments while anticipating barriers, lapses, and changing circumstances.", "children": [{"id": "e4233b22-af65-4a2e-8593-7e08e2d611a0", "type": "subtopic", "title": "Meaningful goal setting", "description": "Students distinguish clinician targets from the client's outcome, performance, and process goals.", "children": [{"id": "01aa4515-4c6b-4c94-ab55-465584706fa2", "type": "concept", "title": "Values-linked outcomes and client-defined success"}, {"id": "5c5cb8b3-66ce-47d2-9e15-f4085f038d99", "type": "concept", "title": "SMART/SMARTER goals and appropriate critique of rigid goal formulas"}, {"id": "f0a15a7a-efec-475e-8eb1-442af3096b4c", "type": "concept", "title": "Approach versus avoidance goals; learning goals versus performance goals"}]}, {"id": "76260251-ca52-40ad-8a31-0e443e7ba0bc", "type": "subtopic", "title": "Action planning and behavior design", "description": "The goal is to make the next step easy to understand and possible in the person's actual environment.", "children": [{"id": "62e460b1-1098-4dae-bd68-188ce99b2d93", "type": "concept", "title": "Who, what, when, where, how often, supports, and required resources"}, {"id": "160ec894-1cd2-47fe-939c-7121e761ecbc", "type": "concept", "title": "Graded tasks, implementation intentions, prompts, defaults, environment redesign, and substitution"}, {"id": "a38c8d10-8b78-4275-b8cd-6d9b1d5bef47", "type": "concept", "title": "Confidence check, barriers, coping plan, and choice among alternatives"}]}, {"id": "71e36d38-4143-4d08-a474-8c0ecbb6f42b", "type": "subtopic", "title": "Self-monitoring, feedback, and lapse recovery", "description": "Students frame monitoring as information for learning rather than surveillance or moral judgment.", "children": [{"id": "27ce248e-bb22-4499-8095-49497d26ff58", "type": "concept", "title": "Food/symptom/activity logs, devices, photos, checklists, and burden-aware data collection"}, {"id": "0f3659ff-80e2-4f82-b11e-4070d3dc4dc3", "type": "concept", "title": "Feedback loops, trend interpretation, reinforcement, and celebrating process"}, {"id": "311a2fda-5e54-46cb-8ee5-1e0eba948ca0", "type": "concept", "title": "Lapse versus relapse, self-compassion, problem solving, maintenance, and planned review"}]}]}, {"id": "908bebf0-72d0-42c6-9fb5-1a51ff37ccbc", "type": "topic", "title": "Cultural Humility, Equity, and Structural Context", "description": "Nutrition advice is never culturally neutral or independent of resources. Students examine their own assumptions, learn from clients' expertise, and adapt care without stereotyping or treating structural barriers as motivation problems.", "children": [{"id": "d4a5ec65-070f-4847-af5c-803bea97ba63", "type": "subtopic", "title": "Cultural humility and reflexivity", "description": "Students practice lifelong self-evaluation and accountability rather than attempting to master a checklist of cultural facts.", "children": [{"id": "794f6bfc-de87-487d-8612-cb0c0131827b", "type": "concept", "title": "Social identity, positionality, power, implicit bias, and cultural countertransference"}, {"id": "4b3f026e-d4c8-4652-853e-b3633afd0a5a", "type": "concept", "title": "Curiosity, respectful inquiry, explanatory models, family/community roles, and food meanings"}, {"id": "e90df10a-aadb-4ec0-83d6-d0e2892a9062", "type": "concept", "title": "Repair after missteps, feedback, accountability, and avoiding exoticizing or essentializing"}]}, {"id": "f2041040-eb2f-41aa-8a46-71e0913cec5f", "type": "subtopic", "title": "Structural determinants and food access", "description": "The point is to incorporate material conditions into the care plan and connect people with support while respecting choice and privacy.", "children": [{"id": "22c62325-749a-482e-8b60-53c0af4f8f87", "type": "concept", "title": "Income, housing, food security, transportation, labor conditions, neighborhood food environments, and policy"}, {"id": "c18631bf-03f7-4410-9da0-8ae4c3df7c1d", "type": "concept", "title": "Screening with consent, stigma-aware response, benefits/referrals, and resource verification"}, {"id": "73f1b1a6-6ec1-476c-b7f4-639e80e9c13b", "type": "concept", "title": "Structural competence, advocacy, documentation, and avoiding unrealistic recommendations"}]}, {"id": "2111b8f1-36cf-408a-8c1b-5b1e966e0673", "type": "subtopic", "title": "Inclusive communication", "description": "Students adapt communication for language, disability, neurodiversity, family structure, gender, age, and religious practice.", "children": [{"id": "def2c6f9-8b11-45c3-9a1c-64ae7840bf54", "type": "concept", "title": "Qualified interpreters, translated materials, teach-back through interpreters, and avoiding use of children as interpreters"}, {"id": "1d8826dd-edee-421c-bc02-3182069939a6", "type": "concept", "title": "Accessible formats, sensory/cognitive needs, augmentative communication, captions, and plain language"}, {"id": "1a6b91cd-7dd0-48d7-883a-84926aba7d35", "type": "concept", "title": "Gender-affirming, weight-neutral, person-first or identity-first language according to preference"}]}]}, {"id": "abcf8366-c8fd-40ff-a508-3c1443f26f1d", "type": "topic", "title": "Health Literacy, Numeracy, and Teach-Back", "description": "Health literacy is a property of communication systems, not a deficit located in a patient. Students learn universal precautions that make nutrition information understandable, actionable, and safer for everyone.", "children": [{"id": "abd8fdb4-f03c-4f0c-a9e9-cac7bdc8ae03", "type": "subtopic", "title": "Plain language and actionable messages", "description": "Students convert technical nutrition content into a clear main message without distorting evidence.", "children": [{"id": "091b0ace-ed94-4077-9f67-1fe8eace37be", "type": "concept", "title": "Audience, communication objective, main message, familiar words, active voice, and logical order"}, {"id": "d2bd3442-5e52-466d-8287-f6c1ef542c1a", "type": "concept", "title": "Chunking, limiting concepts, examples, visuals, white space, and explicit action steps"}, {"id": "ae42346a-5e29-442d-a5ee-dcb20893a0c9", "type": "concept", "title": "Jargon audit, readability as one limited metric, user testing, and revision"}]}, {"id": "1e9440fb-6b4e-42f1-9081-79b3d624cdda", "type": "subtopic", "title": "Numeracy and risk communication", "description": "Students learn to communicate portions, labels, probabilities, trends, and uncertainty without overwhelming or misleading.", "children": [{"id": "baf7c0c7-7f60-4f09-9db2-1e0b89322952", "type": "concept", "title": "Whole numbers, percentages, frequencies, ratios, units, time frames, and denominator clarity"}, {"id": "95b44095-6c76-4a27-9242-831f963e4f9b", "type": "concept", "title": "Absolute versus relative risk, natural frequencies, framing effects, and uncertainty"}, {"id": "e7dc8da1-5e1a-4599-92e0-80feeefa3159", "type": "concept", "title": "Food labels, household measures, graphs, icon arrays, and checking interpretation"}]}, {"id": "5e0ab16b-c688-452d-9c2f-e4fcb5f74694", "type": "subtopic", "title": "Teach-back and show-me", "description": "The purpose is to test the clarity of the educator's explanation, not to test or shame the learner.", "children": [{"id": "2824cc61-f832-4de1-a61c-1172bf941d35", "type": "concept", "title": "Non-shaming invitation, client explanation in their own words, and demonstration of skills"}, {"id": "7d680d75-6bdb-4be5-878f-62dafafba0c5", "type": "concept", "title": "Clarify, re-teach differently, re-check, and document understanding"}, {"id": "ba3c1a11-fe5a-4263-805b-31353bba4f11", "type": "concept", "title": "Use with interpreters, caregivers, discharge plans, devices, and multi-step instructions"}]}]}, {"id": "68bfe8a4-cf5d-4dd6-b0fd-14e92f51afe5", "type": "topic", "title": "Instructional Design and Individual Nutrition Education", "description": "Education is effective when it begins with a learner and a performance need—not with a slide deck. Students design brief individual teaching encounters that align objectives, instruction, practice, and evaluation.", "children": [{"id": "c6a92de7-7001-4452-b384-93c7f4c9dbc6", "type": "subtopic", "title": "Learner and needs analysis", "description": "Students identify what the learner already knows, needs to do, can access, and wants from the encounter.", "children": [{"id": "9ead2963-18db-4f35-a0e6-665d0d4a6ac0", "type": "concept", "title": "Learner characteristics, prior knowledge, misconceptions, motivation, setting, and constraints"}, {"id": "02ec22b4-eabf-4335-bdc8-e9c5f9766ada", "type": "concept", "title": "Knowledge, skill, attitude, behavior, and environmental needs"}, {"id": "4450aae5-2b43-4bb7-8f14-1c0fd79c045c", "type": "concept", "title": "Priority analysis, audience segmentation without stereotyping, and co-design"}]}, {"id": "02b7561a-4213-4d32-95e4-872516ff9288", "type": "subtopic", "title": "Objectives and learning principles", "description": "Students write observable objectives and apply learning science to reduce overload and support retention and transfer.", "children": [{"id": "c28f9474-91e7-4814-a8e0-ca527b031e48", "type": "concept", "title": "Audience-behavior-condition-degree framework and measurable verbs"}, {"id": "eac4998e-d8ea-48e5-b2ce-33d689bd001e", "type": "concept", "title": "Cognitive load, prior knowledge, retrieval practice, spacing, worked examples, and feedback"}, {"id": "906de88f-9d1d-41dd-bcbf-cef66ccac866", "type": "concept", "title": "Adult learning, relevance, experience, autonomy, and immediate application"}]}, {"id": "3c55477a-824f-4a40-8d2e-fc00af54d6cd", "type": "subtopic", "title": "Teaching methods and evaluation", "description": "Students match the method to the objective and gather evidence that learning occurred.", "children": [{"id": "89f7a831-f3ba-4243-86f6-fdb0bb50fe6c", "type": "concept", "title": "Explanation, demonstration, guided practice, problem solving, case, analogy, visual, and teach-back"}, {"id": "4c34fe37-ba0d-4eb5-8084-957345bfbcde", "type": "concept", "title": "Formative checks, observation, return demonstration, scenario transfer, and learner reflection"}, {"id": "08f8b1fd-c5e0-4f3d-b4a0-9493e3c6b47d", "type": "concept", "title": "Immediate learning, later behavior, feasibility, satisfaction, and unintended effects"}]}]}, {"id": "8acc153e-8406-4662-91cc-b88171565ae2", "type": "topic", "title": "Group Education and Facilitation", "description": "Groups can provide efficiency, modeling, social support, and collective problem solving, but they require more than delivering a lecture to several people. Students practice inclusive design and facilitation.", "children": [{"id": "765e74ea-1373-4cfb-821c-37fcb8b28e16", "type": "subtopic", "title": "Group design and psychological safety", "description": "Students define the audience, purpose, format, agreements, accessibility needs, and limits of confidentiality.", "children": [{"id": "a031f0f4-ace3-4b2a-8f72-ac0dbffd2991", "type": "concept", "title": "Open versus closed groups, size, session length, sequence, and participant recruitment"}, {"id": "0eacee65-cc9e-45d7-89a5-ce70c35e0de6", "type": "concept", "title": "Group agreements, confidentiality limits, consent, inclusion, and accessibility"}, {"id": "6520e35b-37f5-4797-8d17-c94098382ec6", "type": "concept", "title": "Facilitator role, co-facilitation, lived-experience expertise, and peer leadership"}]}, {"id": "32b6b9ce-4fa0-4a84-a044-20acf9b1dfad", "type": "subtopic", "title": "Facilitation skills and group dynamics", "description": "The goal is balanced participation, useful dialogue, and progress while responding to conflict or misinformation.", "children": [{"id": "41519b07-79cd-4ea7-8534-b5bad96d5cbd", "type": "concept", "title": "Opening, check-in, questions, reflection, summarizing, transitions, and closure"}, {"id": "f2d489da-ed0c-49f4-bcea-cf901fde4fb6", "type": "concept", "title": "Dominant/quiet participation, subgroup dynamics, conflict, emotion, and difficult moments"}, {"id": "f2e1b4b8-c837-4945-91a3-f5947c78143d", "type": "concept", "title": "Correcting misinformation respectfully, parking lots, time management, and referral boundaries"}]}, {"id": "f9be93d8-98fc-4388-af74-10f94131c7fc", "type": "subtopic", "title": "Participatory learning and evaluation", "description": "Students replace passive information delivery with activities that let participants apply, practice, and learn from one another.", "children": [{"id": "2bc501a6-c948-4833-8171-049ffc6eccde", "type": "concept", "title": "Discussion, demonstration, teach-back, role-play, case, sorting, mapping, cooking, and problem solving"}, {"id": "763d255d-78a5-439a-b1f8-ae6d9ce22e68", "type": "concept", "title": "Universal Design for Learning and multiple means of engagement/representation/action"}, {"id": "06e42283-a78d-48bb-b341-796e6d1549d2", "type": "concept", "title": "Process, learning, confidence, behavior, reach, equity, and participant feedback"}]}]}, {"id": "b86aa83c-8a4d-4545-b39e-b9f6ca55bbc1", "type": "topic", "title": "Educational Materials, Digital Communication, and Misinformation", "description": "Nutrition professionals communicate through handouts, portals, websites, video, social media, and public presentations. Students learn to create accurate, accessible materials and respond to misinformation without amplifying it.", "children": [{"id": "85f4e048-3358-4e0e-896f-5fd3de7ae051", "type": "subtopic", "title": "Material development and usability", "description": "Students design for a real audience and task, then test and revise rather than assuming professional-looking materials are understandable.", "children": [{"id": "b7c4fc45-88f8-4e27-a307-069d43d4297f", "type": "concept", "title": "Content brief, main message, hierarchy, visuals, accessibility, translation, and cultural relevance"}, {"id": "75db364a-c063-4330-8b01-58d46078d99b", "type": "concept", "title": "CDC Clear Communication Index and complementary usability checks"}, {"id": "ff72489f-ee37-4f20-bbe3-aadde39844ae", "type": "concept", "title": "Cognitive interviews, observation, user testing, revision log, and version/date control"}]}, {"id": "b0190a49-31c9-4a23-bd17-872512e847ca", "type": "subtopic", "title": "Digital and social media communication", "description": "Students adapt evidence-based messages to platform constraints while preserving context, privacy, and professional boundaries.", "children": [{"id": "2be06ccc-5414-4e4d-808c-1a9fadc0d640", "type": "concept", "title": "Web, email, patient portal, short video, podcast, infographic, and social media conventions"}, {"id": "2761bae8-886f-4426-9295-7b901bae2fd4", "type": "concept", "title": "Alt text, captions, color contrast, readable graphics, mobile design, and link accessibility"}, {"id": "e8089ab0-9412-46f3-97e4-9072a43e4df1", "type": "concept", "title": "Professional identity, comments, direct messages, permanence, consent, and organizational policy"}]}, {"id": "33a5e391-7c03-48b5-9267-054b995b9ea4", "type": "subtopic", "title": "Misinformation and risk communication", "description": "The aim is to understand the concern, preserve trust, and offer a memorable evidence-based alternative rather than ridicule or overwhelm.", "children": [{"id": "30569f14-7ca0-4133-9ac5-9bc6540a22cd", "type": "concept", "title": "Source, claim, evidence, motive, plausibility, and emotional/social function"}, {"id": "deb3afe2-bc92-4d44-a44d-23da26dec7da", "type": "concept", "title": "Prebunking, fact-first correction, warning, explanation of fallacy, and replacement narrative"}, {"id": "e2474023-b4e3-432a-9e02-66d177f3055e", "type": "concept", "title": "Uncertainty, evolving evidence, false balance, virality, and when not to engage"}]}]}, {"id": "c8e8a6d7-aa09-47d0-af26-65fe43f7753e", "type": "topic", "title": "Weight-Inclusive Practice, Body Image, and Eating-Disorder Safety", "description": "Nutrition counseling can unintentionally reinforce stigma, restriction, or disordered eating. Students learn to reduce harm, recognize warning signs, work within competence, and coordinate timely referral.", "children": [{"id": "1b1a3cf8-64d2-4447-a46a-8e7cb513868d", "type": "subtopic", "title": "Weight stigma and weight-inclusive care", "description": "Students examine how bias affects access, assessment, communication, and outcomes, and practice separating health behaviors from moral judgments about bodies.", "children": [{"id": "d908dd27-500a-445a-a24c-199b13ffc031", "type": "concept", "title": "Explicit and implicit bias, structural stigma, equipment/environment, and prior healthcare harm"}, {"id": "dc3e246b-fccf-4367-8c5b-f94fa52526ac", "type": "concept", "title": "Permission to discuss weight, neutral description, behavior/function outcomes, and individualized preferences"}, {"id": "d43fa7dc-f114-4feb-acfb-3a3d1c9b83e9", "type": "concept", "title": "Weight-centric and weight-inclusive frameworks; evidence, uncertainty, and client choice"}]}, {"id": "632b3601-c7d3-439a-ae14-58292471e95a", "type": "subtopic", "title": "Body image and eating behavior", "description": "The goal is to discuss food and body concerns without diagnosing, prescribing psychotherapy, or normalizing harmful restriction.", "children": [{"id": "e415c7f7-f4a1-4117-955c-b5fd11c23b5b", "type": "concept", "title": "Body image, body dissatisfaction, interoception, restraint, dieting cycles, and compensatory behavior"}, {"id": "5ab08f49-3561-4566-9254-fe732d66efb9", "type": "concept", "title": "Flexible versus rigid eating, hunger/fullness cues, emotional eating, and contextual eating"}, {"id": "60fb183d-540f-4aff-a5b3-f3cd85bd4313", "type": "concept", "title": "Non-diet and intuitive-eating concepts, benefits/limits, cultural context, and medical needs"}]}, {"id": "bfd87f5f-0049-4cf9-940f-7629684ee1b1", "type": "subtopic", "title": "Screening, red flags, and referral", "description": "Students learn to recognize when standard behavior-change counseling is unsafe or insufficient.", "children": [{"id": "71c18ca0-75b4-4af4-9b88-2d331d5e0198", "type": "concept", "title": "Rapid weight change, restriction, bingeing, purging, exercise compulsion, medical instability, and suicidality escalation"}, {"id": "c8ce5809-cfbd-46fe-a8a8-f68a0062077e", "type": "concept", "title": "Validated screening tools as prompts—not diagnoses—and documentation within scope"}, {"id": "4b10fa16-7b24-4ba0-aef5-8b92183bd224", "type": "concept", "title": "Warm referral, interprofessional eating-disorder care, continued nutrition role, and crisis procedures"}]}]}, {"id": "d4a877e2-b103-47b7-906b-c63b918daa34", "type": "topic", "title": "Telehealth, Hybrid Care, and Digital Tools", "description": "Virtual care changes rapport, observation, privacy, access, workflow, and equity. Students learn to design a tele-nutrition encounter intentionally and to use digital tools without displacing human judgment.", "children": [{"id": "a4c942f2-ea84-4637-9376-e7e025f9925e", "type": "subtopic", "title": "Virtual counseling presence", "description": "Students adapt nonverbal and conversational skills to video, telephone, and asynchronous communication.", "children": [{"id": "4dc3dabd-70fa-48ad-b031-09c1b3631a13", "type": "concept", "title": "Camera/eye line, framing, lighting, sound, pacing, screen sharing, and purposeful pauses"}, {"id": "19bf666b-4c62-4df5-bd8c-32a7276ec5c0", "type": "concept", "title": "Opening technology check, identity/location, privacy, emergency plan, and backup channel"}, {"id": "53b40f4d-52c4-497d-9343-a7173a793da5", "type": "concept", "title": "Telephone cues, portal tone, response-time expectations, and asynchronous boundaries"}]}, {"id": "3cf09d0b-74f1-41f1-8711-0f4705fbcaad", "type": "subtopic", "title": "Access, privacy, and hybrid workflow", "description": "The point is to treat digital access and privacy as design requirements rather than client shortcomings.", "children": [{"id": "f2f596c5-11ab-4aeb-88d2-90c8f9cba98f", "type": "concept", "title": "Broadband, devices, digital literacy, language, disability, rural access, and caregiver support"}, {"id": "8a4ad24a-68a8-4d5e-9d39-9886dd1df9ba", "type": "concept", "title": "Consent, secure platforms, recording, messaging, data retention, and local law/policy"}, {"id": "6663cd9a-2dbf-4336-9a80-009a89d86b7e", "type": "concept", "title": "Scheduling, intake, pre-visit materials, interpreter workflow, follow-up, and when in-person care is needed"}]}, {"id": "3ebecda5-c175-46dd-a3ed-73101920198b", "type": "subtopic", "title": "Apps, remote data, and AI", "description": "Students evaluate whether a tool is valid, usable, equitable, secure, and clinically useful before incorporating it.", "children": [{"id": "cbe61c96-3400-40ed-8ace-9a44769c52c3", "type": "concept", "title": "Food logs, wearables, connected devices, decision aids, and patient-generated data"}, {"id": "68264737-1bb0-4c1c-a5b5-0313d7fdcb0f", "type": "concept", "title": "Validity, interoperability, burden, data gaps, bias, commercial incentives, and alert fatigue"}, {"id": "18a0f1db-b747-4000-a6f1-da3a9e9556a6", "type": "concept", "title": "Generative AI: privacy, hallucination, provenance, verification, disclosure, and no identifiable data in public tools"}]}]}, {"id": "c06e53a8-0156-4e23-8214-6e38f47f30cc", "type": "topic", "title": "Documentation, Outcomes, and Practice Operations", "description": "Counseling must be visible to the next clinician and evaluable over time. Students learn concise documentation, outcome measurement, quality improvement, and basic operational realities without reducing care to billing requirements.", "children": [{"id": "62774bf0-321b-4060-9e39-e54262ff32e8", "type": "subtopic", "title": "Clinical documentation and communication", "description": "Students document the reasoning, client perspective, agreed plan, education, understanding, and follow-up in an actionable record.", "children": [{"id": "d9033bf6-2661-4a2c-bcde-c913cbd298b6", "type": "concept", "title": "ADIME/SOAP structure, objective versus subjective data, direct quotes, and neutral language"}, {"id": "b8a5db6c-b157-4bc8-b19f-8384f11363f0", "type": "concept", "title": "Consent, goals, barriers, education method, teach-back, referrals, and monitoring"}, {"id": "46daeb71-1c02-4dab-bb3a-95d90fbfbc3e", "type": "concept", "title": "Information minimization, sensitive content, late entries, corrections, and interprofessional handoff"}]}, {"id": "c6300760-4737-45b8-934c-6a4927a36690", "type": "subtopic", "title": "Outcome and fidelity evaluation", "description": "Students choose measures that show whether counseling was delivered skillfully and whether it helped.", "children": [{"id": "47a46d1a-a6cd-42b4-918e-b9f3310cd59d", "type": "concept", "title": "Alliance, engagement, knowledge, skill, confidence, behavior, clinical, quality-of-life, and access outcomes"}, {"id": "ce4670a6-1c98-4658-a43e-16beb3f6c398", "type": "concept", "title": "Patient-reported outcomes, goal attainment, attrition, reach, dose, fidelity, and unintended effects"}, {"id": "3f24a086-763f-40b7-aa58-62ae82ac5540", "type": "concept", "title": "Baseline/follow-up, measurement burden, missing data, equity stratification, and interpretation"}]}, {"id": "2b060183-2260-4908-829b-3af90e63c268", "type": "subtopic", "title": "Quality, coding, and reimbursement context", "description": "The goal is basic operational literacy: how services are described, supported, improved, and financed varies by setting and jurisdiction.", "children": [{"id": "4fec4014-111c-429a-ab4c-429e895c78c6", "type": "concept", "title": "Plan-Do-Study-Act cycles, audit and feedback, observation rubrics, and client feedback"}, {"id": "616430a3-f3eb-421d-881e-06d25c7fb948", "type": "concept", "title": "Service coding, diagnosis linkage, medical necessity, payer rules, referrals, and documentation requirements"}, {"id": "1af36b37-1039-4440-8781-900b50832444", "type": "concept", "title": "Time, access, no-show policy, group/telehealth context, and verifying current local requirements"}]}]}, {"id": "6312b5a5-45dd-4e54-a955-34175e8960e1", "type": "topic", "title": "Deliberate Practice, Feedback, and Capstone Demonstration", "description": "Counseling competence develops through repeated performance, observation, specific feedback, reflection, and another attempt. The capstone integrates relationship, theory, education, equity, safety, documentation, and evaluation.", "children": [{"id": "7c2ae975-1aeb-4e67-a2e8-f8f0dfeb5976", "type": "subtopic", "title": "Skills observation and feedback", "description": "Students learn to give and receive behavior-specific feedback tied to observable criteria rather than personality judgments.", "children": [{"id": "3f988028-4b99-4c9d-9b88-aab82b926720", "type": "concept", "title": "Recording consent, confidentiality, structured observation, and psychological safety"}, {"id": "b9db7729-166c-44b3-8e86-9aa34433b295", "type": "concept", "title": "Counts/ratios and qualitative coding for questions, reflections, change talk, teach-back, and information giving"}, {"id": "5bb4c8af-4623-49bd-82f7-e2dcbc6405a9", "type": "concept", "title": "Feedback model: observed behavior, effect, alternative, learner response, and agreed practice target"}]}, {"id": "080f38b3-0458-4e31-976b-f3cc9048f628", "type": "subtopic", "title": "Reflective practice and supervision", "description": "The purpose is to notice assumptions, emotion, uncertainty, and limits so they can inform safer practice.", "children": [{"id": "b7649d25-4c68-4bc9-b95d-1f0164dbae2e", "type": "concept", "title": "Reflection-in-action, reflection-on-action, critical incident, and bias check"}, {"id": "ffa9e5c4-5641-4c9a-b357-13e1e17bbfa2", "type": "concept", "title": "Countertransference-like reactions within dietetics, rescue impulse, frustration, and overidentification"}, {"id": "a80104da-408e-4111-902e-744f422c8013", "type": "concept", "title": "Consultation questions, scope limits, supervision use, self-care, and preventing burnout"}]}, {"id": "27df7747-8b8a-4b3f-9f51-ecab2ae2e7e2", "type": "subtopic", "title": "Integrated counseling and education capstone", "description": "Students demonstrate a complete encounter and educational product for a complex simulated client or group.", "children": [{"id": "0f9e7f8b-538f-433d-9993-193887514fbf", "type": "concept", "title": "Preparation, opening, assessment, focus, MI-consistent conversation, shared plan, teach-back, and close"}, {"id": "706d6f8b-e664-44ec-beb8-1cd0be6b0a09", "type": "concept", "title": "Cultural/structural adaptation, eating-disorder safety, telehealth option, referral, and documentation"}, {"id": "44c22f80-7e39-4467-96ea-e7a540f1aded", "type": "concept", "title": "Self-assessment, client/peer/faculty feedback, revision, and development plan"}]}]}], "dbBacked": true}$ncejson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'nutrition-counseling-and-education'
);

update public.learning_paths
set
  title = 'Nutrition Counseling and Education',
  goal = 'Nutrition Counseling and Education',
  summary = 'This advanced undergraduate course develops evidence-informed nutrition counseling, education, and communication skills for diverse individuals and groups. Students integrate person-centered communication, motivational interviewing, behavior-change theory, the Nutrition Care Process, cultural humility, structural context, health literacy, instructional design, group facilitation, digital communication, eating-disorder safety, telehealth, documentation, and evaluation. Repeated simulations and feedback build observable competence in listening, assessment, shared agenda setting, information exchange, action planning, teach-back, group teaching, referral, and professional documentation. The course prepares students for supervised dietetics practice; it does not confer independent clinical or psychotherapy scope.',
  data = $ncejson${"slug": "nutrition-counseling-and-education", "title": "Nutrition Counseling and Education", "description": "This advanced undergraduate course develops evidence-informed nutrition counseling, education, and communication skills for diverse individuals and groups. Students integrate person-centered communication, motivational interviewing, behavior-change theory, the Nutrition Care Process, cultural humility, structural context, health literacy, instructional design, group facilitation, digital communication, eating-disorder safety, telehealth, documentation, and evaluation. Repeated simulations and feedback build observable competence in listening, assessment, shared agenda setting, information exchange, action planning, teach-back, group teaching, referral, and professional documentation. The course prepares students for supervised dietetics practice; it does not confer independent clinical or psychotherapy scope.", "topics": [{"id": "ed9b4d66-4f86-4f18-a2cf-090e93fd6d5f", "type": "topic", "title": "Foundations of Nutrition Counseling and Education", "description": "This opening section distinguishes counseling, education, coaching, health communication, and psychotherapy. Students learn what a nutrition professional can responsibly do, how each approach serves a different purpose, and why client autonomy is the organizing principle.", "children": [{"id": "7200a5a0-6eb7-46b9-ba07-091a7a8243ca", "type": "subtopic", "title": "Counseling, education, and coaching", "description": "Students select the right helping mode instead of defaulting to advice. Counseling supports exploration and change; education builds knowledge or skill; coaching supports self-directed action.", "children": [{"id": "c6d19040-37bb-47b3-8e6f-1349f79a30e4", "type": "concept", "title": "Purpose, stance, typical structure, and indicators for each mode"}, {"id": "44775154-7313-448f-b5c4-2cff69f9e39c", "type": "concept", "title": "Expert-driven, collaborative, and client-led communication"}, {"id": "4cfadd4f-b049-46f0-9c16-44345863ee39", "type": "concept", "title": "Switching modes transparently and asking permission before providing information"}]}, {"id": "433c9f1b-9966-44da-9dd0-73f15995a1fd", "type": "subtopic", "title": "Professional role and scope", "description": "This subtopic clarifies the boundaries of undergraduate practice and the difference between nutrition counseling and mental-health treatment.", "children": [{"id": "14716243-5cc6-4c46-bb62-a93b4a2f3436", "type": "concept", "title": "Dietetics scope, supervision, referral, and jurisdictional variation"}, {"id": "b9e29d91-c4bb-43ef-93bd-9d25329dc943", "type": "concept", "title": "Nutrition diagnosis versus psychiatric diagnosis; coaching versus psychotherapy"}, {"id": "5f7681f0-98d7-4875-ba9a-04021c0575d2", "type": "concept", "title": "Interprofessional roles, handoffs, consultation, and emergency escalation"}]}, {"id": "1af4de62-a808-4925-a780-2dfc6917553b", "type": "subtopic", "title": "Evidence-informed, person-centered practice", "description": "Students learn to integrate research, practitioner expertise, context, and the client's values rather than presenting evidence as a command.", "children": [{"id": "0e50acee-dfd5-4df0-b5e9-c32f7758e4b0", "type": "concept", "title": "Evidence quality, uncertainty, applicability, and shared decisions"}, {"id": "83d1e6fd-fc11-4f1f-8281-1a63e4830b8b", "type": "concept", "title": "Autonomy, dignity, strengths, preferences, lived experience, and treatment burden"}, {"id": "9bb8970e-ef2e-4f2b-bced-c78b447390d2", "type": "concept", "title": "Outcome goals that include function, well-being, access, and quality of life"}]}]}, {"id": "1cd2c17a-81c6-4622-bfe2-69beecb22060", "type": "topic", "title": "Counseling Relationship, Ethics, and Psychological Safety", "description": "A productive relationship is not a soft extra; it determines what information is shared, whether recommendations fit, and whether a person returns. Students practice trustworthy, boundaried, and nonjudgmental care.", "children": [{"id": "bc5a6d3d-73e6-4e85-92d5-563fc9402b2c", "type": "subtopic", "title": "Rapport, alliance, and trust", "description": "Students learn how presence, reliability, warmth, and accurate empathy create a working alliance without pretending to know another person's experience.", "children": [{"id": "fb6641a4-1867-424a-bda3-b9c494ff15f0", "type": "concept", "title": "Opening a session, role clarity, agenda negotiation, and confidentiality"}, {"id": "1fb5afcb-6cc3-4bcc-88f6-441e17858ff9", "type": "concept", "title": "Empathy, genuineness, respect, acceptance, and collaborative language"}, {"id": "1955272c-2e24-4c74-920c-056be3210b56", "type": "concept", "title": "Alliance ruptures, repair, feedback, and maintaining trust when priorities differ"}]}, {"id": "fd8debe3-e481-49b4-85de-52641cda8633", "type": "subtopic", "title": "Ethical practice and boundaries", "description": "The point is to recognize conflicts, power, privacy, and dual-role risks before they harm a client or the profession.", "children": [{"id": "c55a5b67-cb73-4956-9845-ad534f70c62b", "type": "concept", "title": "Autonomy, beneficence, nonmaleficence, justice, veracity, and fidelity"}, {"id": "c80238d2-2d9d-4408-a93a-2c80f467cc26", "type": "concept", "title": "Consent, privacy, record access, gifts, social media, self-disclosure, and conflicts of interest"}, {"id": "8895c0a8-4629-4913-9ad4-15acaf0e45a7", "type": "concept", "title": "Commercial influence, testimonials, supplement sales, sponsorship, and transparent evidence"}]}, {"id": "a3d889e3-540a-4ae1-bfb5-d7e28033fb86", "type": "subtopic", "title": "Trauma-informed communication", "description": "Students use universal precautions that reduce shame and coercion without asking clients to disclose trauma or attempting trauma therapy.", "children": [{"id": "c1e3ffc4-8fe0-4322-85e9-cd1f7377763b", "type": "concept", "title": "Safety, trustworthiness, choice, collaboration, empowerment, and cultural context"}, {"id": "95ea793e-0fe1-4d1a-8b2e-0a1356cb3441", "type": "concept", "title": "Predictability, permission, control over weighing/examination context, and non-shaming language"}, {"id": "ae762c7a-8d12-4629-a561-745e817eb973", "type": "concept", "title": "Recognizing activation, pausing, grounding within scope, and referral to qualified care"}]}]}, {"id": "19748e42-55ea-49eb-bbdf-37833f50bad9", "type": "topic", "title": "Core Communication Micro-Skills", "description": "Micro-skills make collaboration observable and teachable. Students deliberately practice listening, reflection, questioning, summarizing, and information exchange, then examine how each response changes the conversation.", "children": [{"id": "f885d9d6-cc6d-4cd8-8e4a-edfe315150f1", "type": "subtopic", "title": "Attending and nonverbal communication", "description": "Students learn to communicate attention across in-person, telephone, interpreter-mediated, and video encounters.", "children": [{"id": "3a2495b4-2774-48b8-8ce1-3d53a99faa78", "type": "concept", "title": "Eye contact preferences, posture, pacing, silence, facial expression, and vocal tone"}, {"id": "9b418a3b-8649-44ee-9fe7-920f6f681e15", "type": "concept", "title": "Environment, privacy, interruptions, seating, accessibility, and technology"}, {"id": "644f5e3e-587d-465b-ba43-e83b4dc8c9f6", "type": "concept", "title": "Observing without overinterpreting emotion, culture, disability, or neurotype"}]}, {"id": "d0977769-2706-42a6-a4eb-2dee434067ad", "type": "subtopic", "title": "Questions, reflections, and summaries", "description": "The goal is to elicit meaning rather than conduct an interrogation or rush to solutions.", "children": [{"id": "c08deaf1-8cdf-48a0-9589-463b75e83828", "type": "concept", "title": "Open versus closed questions; focused, evocative, and scaling questions"}, {"id": "2143709d-3040-405d-97f6-52fbed4470e9", "type": "concept", "title": "Simple and complex reflections; content, feeling, meaning, and ambivalence"}, {"id": "d2861282-8d85-4b2b-90d2-911303dca4f9", "type": "concept", "title": "Collecting, linking, and transitional summaries; checking accuracy"}]}, {"id": "1010e4a5-8b93-4919-a103-a20cbab85364", "type": "subtopic", "title": "Empathy, affirmation, and information exchange", "description": "Students practice validating effort and perspective while avoiding empty praise or reassurance.", "children": [{"id": "54bb5534-f257-487b-8ea3-c3cedc3f5e46", "type": "concept", "title": "Specific strengths-based affirmations and normalization without minimization"}, {"id": "aa5178d5-ddc4-4b0d-bb6c-1f5a4fec1e88", "type": "concept", "title": "Elicit-provide-elicit, ask-tell-ask, chunking, and choice of information"}, {"id": "91ddc67a-cbc6-4409-85c9-46028f38889d", "type": "concept", "title": "Permission, neutral options, correcting misinformation, and preserving autonomy"}]}]}, {"id": "36583508-ff53-4a50-9a18-c36d470cade3", "type": "topic", "title": "Motivational Interviewing", "description": "Motivational interviewing provides a coherent method for conversations about change when motivation is mixed. Students learn the spirit, processes, and skills while avoiding manipulation or using MI as a script.", "children": [{"id": "95c4fd2b-ccb2-4238-85e7-bb148af14a06", "type": "subtopic", "title": "MI spirit and four processes", "description": "Students ground techniques in partnership, acceptance, compassion, and evocation, moving flexibly through engaging, focusing, evoking, and planning.", "children": [{"id": "22aeb0ad-099f-43ec-b9ba-0f9ceb853efc", "type": "concept", "title": "Partnership, autonomy support, accurate empathy, affirmation, and compassion"}, {"id": "1f30dc3e-48f5-48ac-855a-24c4ef389364", "type": "concept", "title": "Engaging before focusing; shared agenda and target behavior"}, {"id": "858b2c01-5f3d-4aea-9915-d2a20e0ca8ce", "type": "concept", "title": "Evoking before planning; returning to engagement when discord appears"}]}, {"id": "2d3254da-4e4a-4f1e-878a-374805c4deca", "type": "subtopic", "title": "Change talk, sustain talk, and discord", "description": "Students listen for the person's own language about change and respond without arguing against reasons to stay the same.", "children": [{"id": "a49de9f8-7e7c-4204-bd56-5a974288fbff", "type": "concept", "title": "Desire, ability, reasons, need, commitment, activation, and taking steps"}, {"id": "39b828dc-837a-4527-9b52-ca4026dbf437", "type": "concept", "title": "Preparatory versus mobilizing change talk; strength and frequency"}, {"id": "71e69afa-fc2e-4fd3-8c8e-613089002f15", "type": "concept", "title": "Sustain talk versus relational discord; reflections, double-sided reflections, and shifting focus"}]}, {"id": "b5500860-3dd4-4c39-a657-88a8d0c3ab7f", "type": "subtopic", "title": "Evoking and strengthening motivation", "description": "The aim is to help clients hear and organize their own motivations, not to manufacture consent.", "children": [{"id": "a8db2a86-30db-41f9-8ec1-48c46fd1e682", "type": "concept", "title": "Evocative questions, importance/confidence rulers, looking forward/back, and values exploration"}, {"id": "91d4f542-d230-4f58-9760-4c1f77f4214e", "type": "concept", "title": "Selective reflection, elaboration, summaries, and querying extremes with care"}, {"id": "be9c36a5-dd53-4b79-be9f-21415f5650fe", "type": "concept", "title": "Recognizing readiness for planning and avoiding premature action plans"}]}]}, {"id": "1092da14-5fcd-4d88-bd54-62756acd0489", "type": "topic", "title": "Behavior-Change Theory and Case Formulation", "description": "Theories are lenses for explaining behavior and selecting intervention targets. Students compare models, identify their limitations, and build a formulation that includes individual, interpersonal, environmental, and structural influences.", "children": [{"id": "422efb30-9412-459c-a5fe-8d646886b727", "type": "subtopic", "title": "Stage and belief models", "description": "Students use stage and belief constructs as hypotheses—not labels that define a person or dictate a fixed intervention.", "children": [{"id": "73c9e693-217d-4d38-912c-a8c8f2752f2e", "type": "concept", "title": "Transtheoretical Model/stages of change, processes, decisional balance, and self-efficacy"}, {"id": "d307012a-9b8f-49dc-9168-7e43ca91d5af", "type": "concept", "title": "Health Belief Model: susceptibility, severity, benefits, barriers, cues, and efficacy"}, {"id": "32596474-43d4-4431-9036-e22b2f769ea4", "type": "concept", "title": "Theory of Planned Behavior: attitudes, norms, perceived control, intentions, and intention-behavior gap"}]}, {"id": "9282695e-64a0-4aed-83e0-1ea345ad2a35", "type": "subtopic", "title": "Capability, opportunity, motivation, and self-regulation", "description": "This subtopic broadens the analysis beyond willingness by asking whether a behavior is possible, supported, and sustainable.", "children": [{"id": "d56b7c3e-4cb7-42e7-b294-80d34b706097", "type": "concept", "title": "COM-B and Behavior Change Wheel concepts"}, {"id": "daf0351e-1f35-457f-a37d-133467b1cdf8", "type": "concept", "title": "Social Cognitive Theory: reciprocal determinism, modeling, outcome expectations, and self-efficacy"}, {"id": "a7324174-8a99-42c0-938f-206f92920cfb", "type": "concept", "title": "Self-Determination Theory: autonomy, competence, relatedness, and internalization"}]}, {"id": "18d3a13d-ba6b-4958-a7d9-ae42b6828105", "type": "subtopic", "title": "Ecological and systems formulation", "description": "Students connect behavior to family, food environments, institutions, policy, marketing, transportation, and material resources.", "children": [{"id": "0db1b1c4-01ab-468d-9493-c10b4b784f26", "type": "concept", "title": "Social-ecological levels and social determinants of health"}, {"id": "e4df5b65-77e4-4505-9fda-d9e8f929de49", "type": "concept", "title": "Habit, affect, identity, stress, executive function, and automatic versus reflective processes"}, {"id": "202c7f55-36ea-41d0-a96c-5cffc420d469", "type": "concept", "title": "Causal maps, modifiable drivers, leverage points, and avoiding individual-blame explanations"}]}]}, {"id": "8a7fd694-7bcc-41dc-bf5b-34dbce34c1b5", "type": "topic", "title": "Assessment, Readiness, and Shared Agenda", "description": "Good counseling begins with understanding what matters, what is happening, and what is realistically changeable. Students conduct focused assessment without turning the session into data extraction.", "children": [{"id": "d634fc4b-907f-4eae-8d92-fff5872f8d7e", "type": "subtopic", "title": "Whole-person nutrition assessment", "description": "Students connect food patterns with symptoms, medical priorities, function, relationships, culture, resources, and daily routines.", "children": [{"id": "cbbc18d5-3f66-40b7-92c3-0418fb932d88", "type": "concept", "title": "Presenting concern, nutrition history, health data, medications, sleep, movement, stress, and function"}, {"id": "c12a26db-2746-4980-8d23-ef852aafc662", "type": "concept", "title": "Food access, cooking facilities, time, money, transportation, caregiving, and work"}, {"id": "48cd7b21-6385-4c28-b511-081e0d13eaf6", "type": "concept", "title": "Strengths, prior attempts, preferences, fears, supports, and current strategies"}]}, {"id": "a9eb4595-2bb6-411d-9494-7a1376dd0967", "type": "subtopic", "title": "Readiness, confidence, and ambivalence", "description": "The aim is to understand motivation as dynamic and context-specific rather than a fixed trait.", "children": [{"id": "e49466f1-a3fe-4b6d-bd5d-bb12a0676438", "type": "concept", "title": "Importance, confidence, priority, timing, and competing demands"}, {"id": "84831e7c-b194-4dc1-a369-60af8bfad52e", "type": "concept", "title": "Values and discrepancy without confrontation"}, {"id": "63bee6b3-bb87-4b21-be32-bee39103e582", "type": "concept", "title": "Ambivalence, resistance as interaction, autonomy, and when not to pursue change"}]}, {"id": "e40cdfd3-0725-4322-a045-76001ebd10f8", "type": "subtopic", "title": "Collaborative focus and session structure", "description": "Students learn to create enough structure for progress while keeping the client's priorities visible.", "children": [{"id": "6a0662b1-48d1-4cad-8dff-3010d3966869", "type": "concept", "title": "Opening, agenda map, time check, shared focus, transition, summary, and close"}, {"id": "fa851de5-cdb1-472e-90de-38288174dc01", "type": "concept", "title": "Multiple concerns, urgent issues, referral needs, and narrowing scope"}, {"id": "dee3a62e-e640-4ab3-b9cb-30cfbb36afd4", "type": "concept", "title": "Follow-up from prior sessions, continuity, and unfinished topics"}]}]}, {"id": "9f51aa57-f0d2-47b6-86f4-dd5769a4541f", "type": "topic", "title": "Collaborative Goals, Action Planning, and Maintenance", "description": "Plans work when they are meaningful, feasible, specific, and revisable. Students practice translating insight into experiments while anticipating barriers, lapses, and changing circumstances.", "children": [{"id": "e4233b22-af65-4a2e-8593-7e08e2d611a0", "type": "subtopic", "title": "Meaningful goal setting", "description": "Students distinguish clinician targets from the client's outcome, performance, and process goals.", "children": [{"id": "01aa4515-4c6b-4c94-ab55-465584706fa2", "type": "concept", "title": "Values-linked outcomes and client-defined success"}, {"id": "5c5cb8b3-66ce-47d2-9e15-f4085f038d99", "type": "concept", "title": "SMART/SMARTER goals and appropriate critique of rigid goal formulas"}, {"id": "f0a15a7a-efec-475e-8eb1-442af3096b4c", "type": "concept", "title": "Approach versus avoidance goals; learning goals versus performance goals"}]}, {"id": "76260251-ca52-40ad-8a31-0e443e7ba0bc", "type": "subtopic", "title": "Action planning and behavior design", "description": "The goal is to make the next step easy to understand and possible in the person's actual environment.", "children": [{"id": "62e460b1-1098-4dae-bd68-188ce99b2d93", "type": "concept", "title": "Who, what, when, where, how often, supports, and required resources"}, {"id": "160ec894-1cd2-47fe-939c-7121e761ecbc", "type": "concept", "title": "Graded tasks, implementation intentions, prompts, defaults, environment redesign, and substitution"}, {"id": "a38c8d10-8b78-4275-b8cd-6d9b1d5bef47", "type": "concept", "title": "Confidence check, barriers, coping plan, and choice among alternatives"}]}, {"id": "71e36d38-4143-4d08-a474-8c0ecbb6f42b", "type": "subtopic", "title": "Self-monitoring, feedback, and lapse recovery", "description": "Students frame monitoring as information for learning rather than surveillance or moral judgment.", "children": [{"id": "27ce248e-bb22-4499-8095-49497d26ff58", "type": "concept", "title": "Food/symptom/activity logs, devices, photos, checklists, and burden-aware data collection"}, {"id": "0f3659ff-80e2-4f82-b11e-4070d3dc4dc3", "type": "concept", "title": "Feedback loops, trend interpretation, reinforcement, and celebrating process"}, {"id": "311a2fda-5e54-46cb-8ee5-1e0eba948ca0", "type": "concept", "title": "Lapse versus relapse, self-compassion, problem solving, maintenance, and planned review"}]}]}, {"id": "908bebf0-72d0-42c6-9fb5-1a51ff37ccbc", "type": "topic", "title": "Cultural Humility, Equity, and Structural Context", "description": "Nutrition advice is never culturally neutral or independent of resources. Students examine their own assumptions, learn from clients' expertise, and adapt care without stereotyping or treating structural barriers as motivation problems.", "children": [{"id": "d4a5ec65-070f-4847-af5c-803bea97ba63", "type": "subtopic", "title": "Cultural humility and reflexivity", "description": "Students practice lifelong self-evaluation and accountability rather than attempting to master a checklist of cultural facts.", "children": [{"id": "794f6bfc-de87-487d-8612-cb0c0131827b", "type": "concept", "title": "Social identity, positionality, power, implicit bias, and cultural countertransference"}, {"id": "4b3f026e-d4c8-4652-853e-b3633afd0a5a", "type": "concept", "title": "Curiosity, respectful inquiry, explanatory models, family/community roles, and food meanings"}, {"id": "e90df10a-aadb-4ec0-83d6-d0e2892a9062", "type": "concept", "title": "Repair after missteps, feedback, accountability, and avoiding exoticizing or essentializing"}]}, {"id": "f2041040-eb2f-41aa-8a46-71e0913cec5f", "type": "subtopic", "title": "Structural determinants and food access", "description": "The point is to incorporate material conditions into the care plan and connect people with support while respecting choice and privacy.", "children": [{"id": "22c62325-749a-482e-8b60-53c0af4f8f87", "type": "concept", "title": "Income, housing, food security, transportation, labor conditions, neighborhood food environments, and policy"}, {"id": "c18631bf-03f7-4410-9da0-8ae4c3df7c1d", "type": "concept", "title": "Screening with consent, stigma-aware response, benefits/referrals, and resource verification"}, {"id": "73f1b1a6-6ec1-476c-b7f4-639e80e9c13b", "type": "concept", "title": "Structural competence, advocacy, documentation, and avoiding unrealistic recommendations"}]}, {"id": "2111b8f1-36cf-408a-8c1b-5b1e966e0673", "type": "subtopic", "title": "Inclusive communication", "description": "Students adapt communication for language, disability, neurodiversity, family structure, gender, age, and religious practice.", "children": [{"id": "def2c6f9-8b11-45c3-9a1c-64ae7840bf54", "type": "concept", "title": "Qualified interpreters, translated materials, teach-back through interpreters, and avoiding use of children as interpreters"}, {"id": "1d8826dd-edee-421c-bc02-3182069939a6", "type": "concept", "title": "Accessible formats, sensory/cognitive needs, augmentative communication, captions, and plain language"}, {"id": "1a6b91cd-7dd0-48d7-883a-84926aba7d35", "type": "concept", "title": "Gender-affirming, weight-neutral, person-first or identity-first language according to preference"}]}]}, {"id": "abcf8366-c8fd-40ff-a508-3c1443f26f1d", "type": "topic", "title": "Health Literacy, Numeracy, and Teach-Back", "description": "Health literacy is a property of communication systems, not a deficit located in a patient. Students learn universal precautions that make nutrition information understandable, actionable, and safer for everyone.", "children": [{"id": "abd8fdb4-f03c-4f0c-a9e9-cac7bdc8ae03", "type": "subtopic", "title": "Plain language and actionable messages", "description": "Students convert technical nutrition content into a clear main message without distorting evidence.", "children": [{"id": "091b0ace-ed94-4077-9f67-1fe8eace37be", "type": "concept", "title": "Audience, communication objective, main message, familiar words, active voice, and logical order"}, {"id": "d2bd3442-5e52-466d-8287-f6c1ef542c1a", "type": "concept", "title": "Chunking, limiting concepts, examples, visuals, white space, and explicit action steps"}, {"id": "ae42346a-5e29-442d-a5ee-dcb20893a0c9", "type": "concept", "title": "Jargon audit, readability as one limited metric, user testing, and revision"}]}, {"id": "1e9440fb-6b4e-42f1-9081-79b3d624cdda", "type": "subtopic", "title": "Numeracy and risk communication", "description": "Students learn to communicate portions, labels, probabilities, trends, and uncertainty without overwhelming or misleading.", "children": [{"id": "baf7c0c7-7f60-4f09-9db2-1e0b89322952", "type": "concept", "title": "Whole numbers, percentages, frequencies, ratios, units, time frames, and denominator clarity"}, {"id": "95b44095-6c76-4a27-9242-831f963e4f9b", "type": "concept", "title": "Absolute versus relative risk, natural frequencies, framing effects, and uncertainty"}, {"id": "e7dc8da1-5e1a-4599-92e0-80feeefa3159", "type": "concept", "title": "Food labels, household measures, graphs, icon arrays, and checking interpretation"}]}, {"id": "5e0ab16b-c688-452d-9c2f-e4fcb5f74694", "type": "subtopic", "title": "Teach-back and show-me", "description": "The purpose is to test the clarity of the educator's explanation, not to test or shame the learner.", "children": [{"id": "2824cc61-f832-4de1-a61c-1172bf941d35", "type": "concept", "title": "Non-shaming invitation, client explanation in their own words, and demonstration of skills"}, {"id": "7d680d75-6bdb-4be5-878f-62dafafba0c5", "type": "concept", "title": "Clarify, re-teach differently, re-check, and document understanding"}, {"id": "ba3c1a11-fe5a-4263-805b-31353bba4f11", "type": "concept", "title": "Use with interpreters, caregivers, discharge plans, devices, and multi-step instructions"}]}]}, {"id": "68bfe8a4-cf5d-4dd6-b0fd-14e92f51afe5", "type": "topic", "title": "Instructional Design and Individual Nutrition Education", "description": "Education is effective when it begins with a learner and a performance need—not with a slide deck. Students design brief individual teaching encounters that align objectives, instruction, practice, and evaluation.", "children": [{"id": "c6a92de7-7001-4452-b384-93c7f4c9dbc6", "type": "subtopic", "title": "Learner and needs analysis", "description": "Students identify what the learner already knows, needs to do, can access, and wants from the encounter.", "children": [{"id": "9ead2963-18db-4f35-a0e6-665d0d4a6ac0", "type": "concept", "title": "Learner characteristics, prior knowledge, misconceptions, motivation, setting, and constraints"}, {"id": "02ec22b4-eabf-4335-bdc8-e9c5f9766ada", "type": "concept", "title": "Knowledge, skill, attitude, behavior, and environmental needs"}, {"id": "4450aae5-2b43-4bb7-8f14-1c0fd79c045c", "type": "concept", "title": "Priority analysis, audience segmentation without stereotyping, and co-design"}]}, {"id": "02b7561a-4213-4d32-95e4-872516ff9288", "type": "subtopic", "title": "Objectives and learning principles", "description": "Students write observable objectives and apply learning science to reduce overload and support retention and transfer.", "children": [{"id": "c28f9474-91e7-4814-a8e0-ca527b031e48", "type": "concept", "title": "Audience-behavior-condition-degree framework and measurable verbs"}, {"id": "eac4998e-d8ea-48e5-b2ce-33d689bd001e", "type": "concept", "title": "Cognitive load, prior knowledge, retrieval practice, spacing, worked examples, and feedback"}, {"id": "906de88f-9d1d-41dd-bcbf-cef66ccac866", "type": "concept", "title": "Adult learning, relevance, experience, autonomy, and immediate application"}]}, {"id": "3c55477a-824f-4a40-8d2e-fc00af54d6cd", "type": "subtopic", "title": "Teaching methods and evaluation", "description": "Students match the method to the objective and gather evidence that learning occurred.", "children": [{"id": "89f7a831-f3ba-4243-86f6-fdb0bb50fe6c", "type": "concept", "title": "Explanation, demonstration, guided practice, problem solving, case, analogy, visual, and teach-back"}, {"id": "4c34fe37-ba0d-4eb5-8084-957345bfbcde", "type": "concept", "title": "Formative checks, observation, return demonstration, scenario transfer, and learner reflection"}, {"id": "08f8b1fd-c5e0-4f3d-b4a0-9493e3c6b47d", "type": "concept", "title": "Immediate learning, later behavior, feasibility, satisfaction, and unintended effects"}]}]}, {"id": "8acc153e-8406-4662-91cc-b88171565ae2", "type": "topic", "title": "Group Education and Facilitation", "description": "Groups can provide efficiency, modeling, social support, and collective problem solving, but they require more than delivering a lecture to several people. Students practice inclusive design and facilitation.", "children": [{"id": "765e74ea-1373-4cfb-821c-37fcb8b28e16", "type": "subtopic", "title": "Group design and psychological safety", "description": "Students define the audience, purpose, format, agreements, accessibility needs, and limits of confidentiality.", "children": [{"id": "a031f0f4-ace3-4b2a-8f72-ac0dbffd2991", "type": "concept", "title": "Open versus closed groups, size, session length, sequence, and participant recruitment"}, {"id": "0eacee65-cc9e-45d7-89a5-ce70c35e0de6", "type": "concept", "title": "Group agreements, confidentiality limits, consent, inclusion, and accessibility"}, {"id": "6520e35b-37f5-4797-8d17-c94098382ec6", "type": "concept", "title": "Facilitator role, co-facilitation, lived-experience expertise, and peer leadership"}]}, {"id": "32b6b9ce-4fa0-4a84-a044-20acf9b1dfad", "type": "subtopic", "title": "Facilitation skills and group dynamics", "description": "The goal is balanced participation, useful dialogue, and progress while responding to conflict or misinformation.", "children": [{"id": "41519b07-79cd-4ea7-8534-b5bad96d5cbd", "type": "concept", "title": "Opening, check-in, questions, reflection, summarizing, transitions, and closure"}, {"id": "f2d489da-ed0c-49f4-bcea-cf901fde4fb6", "type": "concept", "title": "Dominant/quiet participation, subgroup dynamics, conflict, emotion, and difficult moments"}, {"id": "f2e1b4b8-c837-4945-91a3-f5947c78143d", "type": "concept", "title": "Correcting misinformation respectfully, parking lots, time management, and referral boundaries"}]}, {"id": "f9be93d8-98fc-4388-af74-10f94131c7fc", "type": "subtopic", "title": "Participatory learning and evaluation", "description": "Students replace passive information delivery with activities that let participants apply, practice, and learn from one another.", "children": [{"id": "2bc501a6-c948-4833-8171-049ffc6eccde", "type": "concept", "title": "Discussion, demonstration, teach-back, role-play, case, sorting, mapping, cooking, and problem solving"}, {"id": "763d255d-78a5-439a-b1f8-ae6d9ce22e68", "type": "concept", "title": "Universal Design for Learning and multiple means of engagement/representation/action"}, {"id": "06e42283-a78d-48bb-b341-796e6d1549d2", "type": "concept", "title": "Process, learning, confidence, behavior, reach, equity, and participant feedback"}]}]}, {"id": "b86aa83c-8a4d-4545-b39e-b9f6ca55bbc1", "type": "topic", "title": "Educational Materials, Digital Communication, and Misinformation", "description": "Nutrition professionals communicate through handouts, portals, websites, video, social media, and public presentations. Students learn to create accurate, accessible materials and respond to misinformation without amplifying it.", "children": [{"id": "85f4e048-3358-4e0e-896f-5fd3de7ae051", "type": "subtopic", "title": "Material development and usability", "description": "Students design for a real audience and task, then test and revise rather than assuming professional-looking materials are understandable.", "children": [{"id": "b7c4fc45-88f8-4e27-a307-069d43d4297f", "type": "concept", "title": "Content brief, main message, hierarchy, visuals, accessibility, translation, and cultural relevance"}, {"id": "75db364a-c063-4330-8b01-58d46078d99b", "type": "concept", "title": "CDC Clear Communication Index and complementary usability checks"}, {"id": "ff72489f-ee37-4f20-bbe3-aadde39844ae", "type": "concept", "title": "Cognitive interviews, observation, user testing, revision log, and version/date control"}]}, {"id": "b0190a49-31c9-4a23-bd17-872512e847ca", "type": "subtopic", "title": "Digital and social media communication", "description": "Students adapt evidence-based messages to platform constraints while preserving context, privacy, and professional boundaries.", "children": [{"id": "2be06ccc-5414-4e4d-808c-1a9fadc0d640", "type": "concept", "title": "Web, email, patient portal, short video, podcast, infographic, and social media conventions"}, {"id": "2761bae8-886f-4426-9295-7b901bae2fd4", "type": "concept", "title": "Alt text, captions, color contrast, readable graphics, mobile design, and link accessibility"}, {"id": "e8089ab0-9412-46f3-97e4-9072a43e4df1", "type": "concept", "title": "Professional identity, comments, direct messages, permanence, consent, and organizational policy"}]}, {"id": "33a5e391-7c03-48b5-9267-054b995b9ea4", "type": "subtopic", "title": "Misinformation and risk communication", "description": "The aim is to understand the concern, preserve trust, and offer a memorable evidence-based alternative rather than ridicule or overwhelm.", "children": [{"id": "30569f14-7ca0-4133-9ac5-9bc6540a22cd", "type": "concept", "title": "Source, claim, evidence, motive, plausibility, and emotional/social function"}, {"id": "deb3afe2-bc92-4d44-a44d-23da26dec7da", "type": "concept", "title": "Prebunking, fact-first correction, warning, explanation of fallacy, and replacement narrative"}, {"id": "e2474023-b4e3-432a-9e02-66d177f3055e", "type": "concept", "title": "Uncertainty, evolving evidence, false balance, virality, and when not to engage"}]}]}, {"id": "c8e8a6d7-aa09-47d0-af26-65fe43f7753e", "type": "topic", "title": "Weight-Inclusive Practice, Body Image, and Eating-Disorder Safety", "description": "Nutrition counseling can unintentionally reinforce stigma, restriction, or disordered eating. Students learn to reduce harm, recognize warning signs, work within competence, and coordinate timely referral.", "children": [{"id": "1b1a3cf8-64d2-4447-a46a-8e7cb513868d", "type": "subtopic", "title": "Weight stigma and weight-inclusive care", "description": "Students examine how bias affects access, assessment, communication, and outcomes, and practice separating health behaviors from moral judgments about bodies.", "children": [{"id": "d908dd27-500a-445a-a24c-199b13ffc031", "type": "concept", "title": "Explicit and implicit bias, structural stigma, equipment/environment, and prior healthcare harm"}, {"id": "dc3e246b-fccf-4367-8c5b-f94fa52526ac", "type": "concept", "title": "Permission to discuss weight, neutral description, behavior/function outcomes, and individualized preferences"}, {"id": "d43fa7dc-f114-4feb-acfb-3a3d1c9b83e9", "type": "concept", "title": "Weight-centric and weight-inclusive frameworks; evidence, uncertainty, and client choice"}]}, {"id": "632b3601-c7d3-439a-ae14-58292471e95a", "type": "subtopic", "title": "Body image and eating behavior", "description": "The goal is to discuss food and body concerns without diagnosing, prescribing psychotherapy, or normalizing harmful restriction.", "children": [{"id": "e415c7f7-f4a1-4117-955c-b5fd11c23b5b", "type": "concept", "title": "Body image, body dissatisfaction, interoception, restraint, dieting cycles, and compensatory behavior"}, {"id": "5ab08f49-3561-4566-9254-fe732d66efb9", "type": "concept", "title": "Flexible versus rigid eating, hunger/fullness cues, emotional eating, and contextual eating"}, {"id": "60fb183d-540f-4aff-a5b3-f3cd85bd4313", "type": "concept", "title": "Non-diet and intuitive-eating concepts, benefits/limits, cultural context, and medical needs"}]}, {"id": "bfd87f5f-0049-4cf9-940f-7629684ee1b1", "type": "subtopic", "title": "Screening, red flags, and referral", "description": "Students learn to recognize when standard behavior-change counseling is unsafe or insufficient.", "children": [{"id": "71c18ca0-75b4-4af4-9b88-2d331d5e0198", "type": "concept", "title": "Rapid weight change, restriction, bingeing, purging, exercise compulsion, medical instability, and suicidality escalation"}, {"id": "c8ce5809-cfbd-46fe-a8a8-f68a0062077e", "type": "concept", "title": "Validated screening tools as prompts—not diagnoses—and documentation within scope"}, {"id": "4b10fa16-7b24-4ba0-aef5-8b92183bd224", "type": "concept", "title": "Warm referral, interprofessional eating-disorder care, continued nutrition role, and crisis procedures"}]}]}, {"id": "d4a877e2-b103-47b7-906b-c63b918daa34", "type": "topic", "title": "Telehealth, Hybrid Care, and Digital Tools", "description": "Virtual care changes rapport, observation, privacy, access, workflow, and equity. Students learn to design a tele-nutrition encounter intentionally and to use digital tools without displacing human judgment.", "children": [{"id": "a4c942f2-ea84-4637-9376-e7e025f9925e", "type": "subtopic", "title": "Virtual counseling presence", "description": "Students adapt nonverbal and conversational skills to video, telephone, and asynchronous communication.", "children": [{"id": "4dc3dabd-70fa-48ad-b031-09c1b3631a13", "type": "concept", "title": "Camera/eye line, framing, lighting, sound, pacing, screen sharing, and purposeful pauses"}, {"id": "19bf666b-4c62-4df5-bd8c-32a7276ec5c0", "type": "concept", "title": "Opening technology check, identity/location, privacy, emergency plan, and backup channel"}, {"id": "53b40f4d-52c4-497d-9343-a7173a793da5", "type": "concept", "title": "Telephone cues, portal tone, response-time expectations, and asynchronous boundaries"}]}, {"id": "3cf09d0b-74f1-41f1-8711-0f4705fbcaad", "type": "subtopic", "title": "Access, privacy, and hybrid workflow", "description": "The point is to treat digital access and privacy as design requirements rather than client shortcomings.", "children": [{"id": "f2f596c5-11ab-4aeb-88d2-90c8f9cba98f", "type": "concept", "title": "Broadband, devices, digital literacy, language, disability, rural access, and caregiver support"}, {"id": "8a4ad24a-68a8-4d5e-9d39-9886dd1df9ba", "type": "concept", "title": "Consent, secure platforms, recording, messaging, data retention, and local law/policy"}, {"id": "6663cd9a-2dbf-4336-9a80-009a89d86b7e", "type": "concept", "title": "Scheduling, intake, pre-visit materials, interpreter workflow, follow-up, and when in-person care is needed"}]}, {"id": "3ebecda5-c175-46dd-a3ed-73101920198b", "type": "subtopic", "title": "Apps, remote data, and AI", "description": "Students evaluate whether a tool is valid, usable, equitable, secure, and clinically useful before incorporating it.", "children": [{"id": "cbe61c96-3400-40ed-8ace-9a44769c52c3", "type": "concept", "title": "Food logs, wearables, connected devices, decision aids, and patient-generated data"}, {"id": "68264737-1bb0-4c1c-a5b5-0313d7fdcb0f", "type": "concept", "title": "Validity, interoperability, burden, data gaps, bias, commercial incentives, and alert fatigue"}, {"id": "18a0f1db-b747-4000-a6f1-da3a9e9556a6", "type": "concept", "title": "Generative AI: privacy, hallucination, provenance, verification, disclosure, and no identifiable data in public tools"}]}]}, {"id": "c06e53a8-0156-4e23-8214-6e38f47f30cc", "type": "topic", "title": "Documentation, Outcomes, and Practice Operations", "description": "Counseling must be visible to the next clinician and evaluable over time. Students learn concise documentation, outcome measurement, quality improvement, and basic operational realities without reducing care to billing requirements.", "children": [{"id": "62774bf0-321b-4060-9e39-e54262ff32e8", "type": "subtopic", "title": "Clinical documentation and communication", "description": "Students document the reasoning, client perspective, agreed plan, education, understanding, and follow-up in an actionable record.", "children": [{"id": "d9033bf6-2661-4a2c-bcde-c913cbd298b6", "type": "concept", "title": "ADIME/SOAP structure, objective versus subjective data, direct quotes, and neutral language"}, {"id": "b8a5db6c-b157-4bc8-b19f-8384f11363f0", "type": "concept", "title": "Consent, goals, barriers, education method, teach-back, referrals, and monitoring"}, {"id": "46daeb71-1c02-4dab-bb3a-95d90fbfbc3e", "type": "concept", "title": "Information minimization, sensitive content, late entries, corrections, and interprofessional handoff"}]}, {"id": "c6300760-4737-45b8-934c-6a4927a36690", "type": "subtopic", "title": "Outcome and fidelity evaluation", "description": "Students choose measures that show whether counseling was delivered skillfully and whether it helped.", "children": [{"id": "47a46d1a-a6cd-42b4-918e-b9f3310cd59d", "type": "concept", "title": "Alliance, engagement, knowledge, skill, confidence, behavior, clinical, quality-of-life, and access outcomes"}, {"id": "ce4670a6-1c98-4658-a43e-16beb3f6c398", "type": "concept", "title": "Patient-reported outcomes, goal attainment, attrition, reach, dose, fidelity, and unintended effects"}, {"id": "3f24a086-763f-40b7-aa58-62ae82ac5540", "type": "concept", "title": "Baseline/follow-up, measurement burden, missing data, equity stratification, and interpretation"}]}, {"id": "2b060183-2260-4908-829b-3af90e63c268", "type": "subtopic", "title": "Quality, coding, and reimbursement context", "description": "The goal is basic operational literacy: how services are described, supported, improved, and financed varies by setting and jurisdiction.", "children": [{"id": "4fec4014-111c-429a-ab4c-429e895c78c6", "type": "concept", "title": "Plan-Do-Study-Act cycles, audit and feedback, observation rubrics, and client feedback"}, {"id": "616430a3-f3eb-421d-881e-06d25c7fb948", "type": "concept", "title": "Service coding, diagnosis linkage, medical necessity, payer rules, referrals, and documentation requirements"}, {"id": "1af36b37-1039-4440-8781-900b50832444", "type": "concept", "title": "Time, access, no-show policy, group/telehealth context, and verifying current local requirements"}]}]}, {"id": "6312b5a5-45dd-4e54-a955-34175e8960e1", "type": "topic", "title": "Deliberate Practice, Feedback, and Capstone Demonstration", "description": "Counseling competence develops through repeated performance, observation, specific feedback, reflection, and another attempt. The capstone integrates relationship, theory, education, equity, safety, documentation, and evaluation.", "children": [{"id": "7c2ae975-1aeb-4e67-a2e8-f8f0dfeb5976", "type": "subtopic", "title": "Skills observation and feedback", "description": "Students learn to give and receive behavior-specific feedback tied to observable criteria rather than personality judgments.", "children": [{"id": "3f988028-4b99-4c9d-9b88-aab82b926720", "type": "concept", "title": "Recording consent, confidentiality, structured observation, and psychological safety"}, {"id": "b9db7729-166c-44b3-8e86-9aa34433b295", "type": "concept", "title": "Counts/ratios and qualitative coding for questions, reflections, change talk, teach-back, and information giving"}, {"id": "5bb4c8af-4623-49bd-82f7-e2dcbc6405a9", "type": "concept", "title": "Feedback model: observed behavior, effect, alternative, learner response, and agreed practice target"}]}, {"id": "080f38b3-0458-4e31-976b-f3cc9048f628", "type": "subtopic", "title": "Reflective practice and supervision", "description": "The purpose is to notice assumptions, emotion, uncertainty, and limits so they can inform safer practice.", "children": [{"id": "b7649d25-4c68-4bc9-b95d-1f0164dbae2e", "type": "concept", "title": "Reflection-in-action, reflection-on-action, critical incident, and bias check"}, {"id": "ffa9e5c4-5641-4c9a-b357-13e1e17bbfa2", "type": "concept", "title": "Countertransference-like reactions within dietetics, rescue impulse, frustration, and overidentification"}, {"id": "a80104da-408e-4111-902e-744f422c8013", "type": "concept", "title": "Consultation questions, scope limits, supervision use, self-care, and preventing burnout"}]}, {"id": "27df7747-8b8a-4b3f-9f51-ecab2ae2e7e2", "type": "subtopic", "title": "Integrated counseling and education capstone", "description": "Students demonstrate a complete encounter and educational product for a complex simulated client or group.", "children": [{"id": "0f9e7f8b-538f-433d-9993-193887514fbf", "type": "concept", "title": "Preparation, opening, assessment, focus, MI-consistent conversation, shared plan, teach-back, and close"}, {"id": "706d6f8b-e664-44ec-beb8-1cd0be6b0a09", "type": "concept", "title": "Cultural/structural adaptation, eating-disorder safety, telehealth option, referral, and documentation"}, {"id": "44c22f80-7e39-4467-96ea-e7a540f1aded", "type": "concept", "title": "Self-assessment, client/peer/faculty feedback, revision, and development plan"}]}]}], "dbBacked": true}$ncejson$::jsonb,
  is_catalog = true,
  is_private = false,
  owner_id = null,
  kind = 'course',
  visibility = 'public',
  updated_at = now()
where slug = 'nutrition-counseling-and-education'
  and (kind is null or kind = 'course');
